// DOC: Join saved stylesheet rules to the current DOM. Media activity and cascade are not inferred from selector matching.
async function connectCSS(work,report){
 const sources=CSS_REFERENCE.sources, byName=new Map(sources.map(s=>[s.file,s])), references=[], active=new Set(), dependencies=[], findings=[], matches=[], nodes=[], nodeMap=new Map();
 const add=(name,via,media)=>{const s=byName.get(name);if(!s)return;references.push({source:name,sha256:s.sha256,via,media:media||null,verification:'SAVED_REFERENCE_NOT_LIVE_HASH_VERIFIED'});active.add(s.sha256);};
 for(const e of qa('link[rel~="stylesheet"]',work)){try{const u=new URL(e.getAttribute('href'),report.sourceURL);if(u.origin===new URL(BASE).origin)add(u.pathname.split('/').pop(),'HTML_LINK',e.getAttribute('media'));}catch{}}
 for(const r of CSS_REFERENCE.records.filter(r=>r.keyword==='import')){const m=r.prelude.match(/^url\(\s*['"]?([^'"\s)]+)['"]?\s*\)\s*(.*)$/);if(!m)continue;dependencies.push({ruleId:r.id,from:r.source,to:m[1],media:m[2]||null});if(active.has(r.sha256))add(m[1],'CSS_IMPORT',m[2]);}
 const legal=[...report.statutoryRecords.map(r=>({id:r.canonicalId,path:r.xpath})),...(report.bill?.sections||[]).map(r=>({id:r.canonicalId,path:r.xpath})),...(report.comparison?.records||[]).map(r=>({id:r.canonicalId,path:r.xpath})),...(report.statuteChain?.records||[]).filter(r=>r.entityType!=='LEGISLATIVE_CROSS_REFERENCE').map(r=>({id:r.canonicalId,path:r.xpath}))];
 const resolve=e=>{if(nodeMap.has(e))return nodeMap.get(e);const path=xpath(e),id=nodes.length;const owners=legal.filter(r=>r.path&&(path===r.path||path.startsWith(r.path+'/'))).map(r=>r.id);nodes.push({id,xpath:path,tag:e.localName,elementId:e.id||null,legalIds:[...new Set(owners)]});nodeMap.set(e,id);return id;};
 const rules=CSS_REFERENCE.records.filter(r=>active.has(r.sha256)&&r.type==='qualified-rule');
 for(const r of rules){try{const es=qa(r.selector,work);matches.push({ruleId:r.id,nodeIds:es.map(resolve),status:'STATIC_SELECTOR_MATCH'});}catch(e){findings.push({id:'DET-CSS-SELECTOR',ruleId:r.id,message:String(e.message)});}}
 const amendmentEvidence=[];for(const e of qa('.blue_text,.red_text,.deltaxml-new,.deltaxml-old,font[color="red"],font[color="blue"],strike',work)){const old=e.matches('.red_text,.deltaxml-old,font[color="red"],strike'), newer=e.matches('.blue_text,.deltaxml-new,font[color="blue"]');const nodeId=resolve(e);if(!nodes[nodeId].legalIds.length)continue;amendmentEvidence.push({nodeId,classification:old&&newer?'CONFLICT':old?'OLD_CANDIDATE':'NEW_CANDIDATE',ruleIds:matches.filter(m=>m.nodeIds.includes(nodeId)&&rules.find(r=>r.id===m.ruleId)?.declarations.some(d=>['color','text-decoration','font-style'].includes(d.property))).map(m=>m.ruleId),verification:'PRESENTATION_EVIDENCE_NOT_LEGAL_VERSION_PROOF'});}
 return {format:'CA-CSS-CONNECTION-V1',captureSHA256:report.captureSHA256,referenceSources:sources,references,dependencies,rules,nodes,matches,amendmentEvidence,findings,summary:{referenceSources:sources.length,linkedUniqueSources:active.size,rules:rules.length,matchedRules:matches.filter(m=>m.nodeIds.length).length,selectorErrors:findings.length,nodes:nodes.length,legalNodes:nodes.filter(n=>n.legalIds.length).length,edges:matches.reduce((n,m)=>n+m.nodeIds.length,0),amendmentEvidence:amendmentEvidence.length},limitations:'Static matching against saved stylesheet definitions; no live byte equivalence, computed cascade, media activation or legal amendment inference.'};
}

